<template>
  <div class="hot">
    <el-button type="text" class="back-btn" @click="back">
      <i class="el-icon-arrow-left" style="font-size: 20px;"></i>
    </el-button>
    <div class="box-card">
      <div class="search-content flex-center">
        <div style="width: 80px"></div>
        <div style="flex: 1;text-align: center">
          <el-input prefix-icon="el-icon-search" placeholder="一句话搜模板，例如：科技感转场" clearable
                    class="search-input" v-model="searchText"></el-input>
        </div>
        <div class="guide" style="margin-right: 15px" @click="guideVisible = true">
          <i class="el-icon-s-opportunity" style="margin-right: 4px;"></i>
          使用指南
        </div>
      </div>
      <div class="tags">
        <el-tag size="small" class="tag" :class="{ 'tag-active': activeTag === '全部推荐' }"
                @click="tagFilter('全部推荐')">全部推荐
        </el-tag>
        <el-tag v-for="(tag, index) in classifies" :key="index" size="small" class="tag"
                :class="{ 'tag-active': tag.name === activeTag }" @click="tagFilter(tag.name)">
          {{ tag.name }}
        </el-tag>
      </div>
      <div class="hot-list">
        <div style="aspect-ratio: 9 / 16;">
          <div class="upload-card" @click="uploadDialogVisible = true">
            <i class="el-icon-shangchuan" style="font-size: 28px"></i>
            <span style="font-size: 12px;margin-top: 8px">上传爆款视频</span>
          </div>
        </div>
        <div v-for="item in processFile" :key="item.id" class="video-card">
          <div class="figure-image-wrapper shining" style="width: 100% !important; height: 100% !important">
            <el-image style="width: 100%; height: 100%;border-radius: 8px;filter: blur(15px);opacity: 0.8"
                      :src="require('/public/images/4.jpg')" fit="cover">
            </el-image>
            <div class="shine-layer"></div>
          </div>
          <div class="file-progress">
            <div>视频上传中</div>
            <div style="width: 10px;text-align: left;margin-left: 5px;font-size: 22px">{{ dot }}</div>
          </div>
          <div class="video-title">{{ item.name }}</div>
        </div>
        <div v-for="(video, index) in filter_hots" :key="index" @click="selectVideo(video)"
             :class="{ 'video-active': select_hots.id === video.id }" class="video-card"
             @contextmenu.stop="handleRightClick(video, $event)"
             @mouseleave="video.isHover = false" @mouseenter="video.isHover = true">
          <el-tag size="mini" v-if="video.category" class="video-tag"
                  :style="{ backgroundColor: classifies.find(item => item.name === video.category).color }">
            {{ video.category }}
          </el-tag>
          <div class="selection-tick" v-if="select_hots.id === video.id">
            <i class="el-icon-check" style="padding: 2px"></i>
          </div>
          <template v-if="!video.isHover">
            <el-image class="hot-img" :src="video.picture" fit="cover"></el-image>
            <div class="video-title">{{ video.name }}</div>
          </template>
          <template v-else>
            <video class="hot-img" style="object-fit: cover;" :src="video.filepath" loop muted autoplay></video>
            <div class="video-title-hover">
              <div style="margin-bottom: 8px">{{ video.name }}</div>
              <div style="display: flex;justify-content: center;align-items: center">
                <i class="el-icon-video-play" style="font-size: 14px"></i>
                <div style="margin-left: 8px;flex: 1">{{ formattedDuration(video.duration) }}</div>
                <i class="el-icon-film" style="font-size: 14px"></i>
                <div style="margin-left: 8px;" v-if="video.segments">{{ video.segments.length + '分镜' }}</div>
              </div>
            </div>
          </template>
        </div>
        <div :style="menuStyle" v-if="rightMenuVisible" style="padding: 8px 12px">
          <div class="material-function" @click="preview">
            <i class="el-icon-view menu-icon"></i>
            播放
          </div>
          <div class="material-function" @click="rename">
            <i class="el-icon-edit-outline menu-icon"></i>
            重命名
          </div>
          <div class="material-function" @click="removeHot">
            <i class="el-icon-delete-solid menu-icon"></i>
            删除
          </div>
          <div class="material-function" @click="showDetail">
            <i class="el-icon-document menu-icon"></i>
            分镜详情
          </div>
        </div>
      </div>
    </div>
    <div style="text-align: center; margin-top: 12px;">
      <el-button type="primary" class="foot-btn" @click="duplicate">一键复刻</el-button>
    </div>
    <el-dialog class="upload-dialog" :visible.sync="uploadDialogVisible" width="600px"
               title="上传爆款视频" :before-close="beforeUploadClose">
      <el-upload
          v-if="!use_link"
          drag
          ref="hotUpload"
          class="video-uploader"
          style="width: 100%"
          action="#"
          :http-request="handleUploadHot"
          :on-change="handleHotChange"
          :on-remove="handleHotRemove"
          :file-list.sync="hotFileList"
          accept=".mp4, .mov"
          :auto-upload="false"
          :limit="6"
          :on-exceed="handleExceed"
          :disabled="loading"
          multiple>
        <i class="el-icon-upload"></i>
        <div class="el-upload__text">将文件拖到此处，或<em>点击上传</em></div>
      </el-upload>

      <div class="flex-center" style="margin: 10px 0 5px 0">
        <el-checkbox v-model="use_link"></el-checkbox>
        <div style="font-size: 15px;font-weight: bold;flex: 1">使用链接上传</div>
      </div>
      <el-input prefix-icon="el-icon-link" v-model="dy_link" placeholder="粘贴抖音视频分享链接上传"
                :disabled="!use_link"></el-input>
      <div style="line-height: 50px">
        <el-radio-group v-model="withAsr">
          <el-radio :label="true">有文案复刻</el-radio>
          <el-radio :label="false">无文案复刻</el-radio>
        </el-radio-group>
      </div>
      <div style="margin-bottom: 5px;font-size: 15px;font-weight: bold">分类</div>
      <div class="classifies">
        <el-tag v-for="(tag, index) in classifies" :key="index" size="small" class="tag"
                :class="{ 'tag-active': tag.name === classify }" @click="classify = tag.name">
          {{ tag.name }}
        </el-tag>
      </div>
      <div style="margin: 10px 0 5px 0;font-size: 15px;font-weight: bold">标签</div>
      <el-input v-model="uploadTag" placeholder="多标签使用逗号(，)分隔，用于匹配搜索"></el-input>
      <span slot="footer" class="dialog-footer">
        <el-button @click="beforeUploadClose" size="small">取消</el-button>
        <el-button type="primary" @click="handleSubmit" size="small" :loading="loading">
          {{ loading? '上传中': '确认上传' }}</el-button>
      </span>
    </el-dialog>
    <el-dialog class="preview-dialog" :visible.sync="previewDialogVisible" :before-close="beforePreviewClose"
               :width="aspectRatio < 1? '720px' : '420px'" top="10vh">
      <div style="width: 100%;text-align: center">
        <video style="border-radius: 10px;width: calc(100% - 40px);object-fit: cover"
               ref="video" :src="preview_src" @ended="isPlaying = false" controls>
        </video>
      </div>
    </el-dialog>
    <el-dialog class="upload-dialog" :visible.sync="renameDialogVisible" width="600px" title="重命名视频名称">
      <div style="margin: 10px 0 5px 0;font-size: 15px;font-weight: bold">原名称</div>
      <el-input v-model="form.original" readonly></el-input>
      <div style="margin: 10px 0 5px 0;font-size: 15px;font-weight: bold">新名称</div>
      <el-input v-model="form.name"  placeholder="请输入新名称"></el-input>
      <span slot="footer" class="dialog-footer">
        <el-button @click="renameDialogVisible = false" size="small">取消</el-button>
        <el-button type="primary" @click="sureRename" size="small">确认</el-button>
      </span>
    </el-dialog>
    <el-dialog class="detail-dialog" :visible.sync="detailDialogVisible" width="800px" title="爆款视频分镜详情">
      <div class="detail-list">
        <el-descriptions title="基础信息" :column="2" border :labelStyle="{'width': '120px','text-align': 'center'}">
          <el-descriptions-item label="视频名称">
            {{ logInfo.name }}
          </el-descriptions-item>
          <el-descriptions-item label="视频时长" :contentStyle="{'width': '307px'}">
            {{ logInfo.duration ? logInfo.duration.toFixed(2) + 's' : '' }}
          </el-descriptions-item>
          <el-descriptions-item label="上传时间" :contentStyle="{'width': '307px'}">
            {{ logInfo.create_time ? logInfo.create_time.replace('T', ' ').split('.')[0] : '' }}
          </el-descriptions-item>
          <el-descriptions-item label="完成时间" :contentStyle="{'width': '307px'}">
            {{ logInfo.updated_at ? logInfo.updated_at.replace('T', ' ').split('.')[0] : '' }}
          </el-descriptions-item>
          <el-descriptions-item label="复刻类别" :contentStyle="{'width': '307px'}"  :span="2">
            {{ logInfo.asr_enabled ? '有文案复刻' : '无文案复刻' }}
          </el-descriptions-item>
          <el-descriptions-item label="文案内容" :span="2">
            {{ logInfo.content ? logInfo.content : '无文案' }}
          </el-descriptions-item>
        </el-descriptions>
        <template v-if="logInfo.grouped_analysis_result">
          <el-divider content-position="left">爆款视频分镜分析</el-divider>
          <div class="group-card">
            <div class="group-title">视频分镜分组分析</div>
            <div class="group-content" :title="logInfo.grouped_analysis_result.reason">
              {{ logInfo.grouped_analysis_result.reason }}
            </div>
            <div class="groups-segment" v-if="logInfo.grouped_analysis_result">
              <div class="group-segment" v-for="(group,group_index) in logInfo.grouped_analysis_result.segmentGroups"
                   :key="group_index">
                <div class="segment-title"
                     :style="{ width: ((group.segments.length - 1) * 100 + 80) + 'px' }"
                     :title="group.contentSummary">
                  {{ group.contentSummary }}
                </div>
                <div class="material-list">
                  <div class="material-item" v-for="(material,material_index) in group.segments"
                       :key="material_index">
                    <el-image class="material-item-img" :src="material.screenshot_path"></el-image>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <el-divider content-position="left">分镜详情</el-divider>
          <el-collapse v-model="activeCollapse">
            <el-collapse-item title="LLM 分析" name="1">
              <div>分析结果</div>
              <div class="llm-thought-process">
                <div v-for="(item, index) in logInfo.grouped_analysis_result.segmentGroups" :key="index">
                  <div class="font-weight">分镜组{{ index + 1 }}({{ item.contentSummary }})</div>
                  <div v-for="(segment, segment_index) in item.segments" :key="segment_index" style="margin-left: 50px">
                    <div v-html="marked(segment.description)"></div>
                  </div>
                </div>
              </div>
            </el-collapse-item>
          </el-collapse>
        </template>
      </div>
    </el-dialog>
    <el-dialog class="guide-dialog" :visible.sync="guideVisible" width="800px">
      <div slot="title" class="guide-dialog-title">
        {{ nextType === 'hot_montage' ? '音画不同步爆款复刻' : '音画同步爆款复刻' }} - 使用指南
      </div>
      <div class="guide-dialog-body" v-if="nextType === 'hot_montage'">
        <div class="guide-item">
          <div class="guide-index">1</div>
          <div style="flex: 1">上传爆款视频：可选择视频文件上传、也可通过抖音分享链接上传</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">2</div>
          <div style="flex: 1">选择爆款视频后点击一键复刻按钮</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">3</div>
          <div style="flex: 1">选择素材、数字人形象，并设置声音、音乐和字幕样式</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">4</div>
          <div style="flex: 1">进入文案编辑页，可选择 AI 批量生成或手动添加文案</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">5</div>
          <div style="flex: 1">在文案列表中，可以修改或删除已生成的文案。</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">6</div>
          <div style="flex: 1">输入混剪要求(可不填)、设置人物形象出镜比例、选择语言、设置背景音乐</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">7</div>
          <div style="flex: 1">混剪后可预览，通过增删分镜或与AI聊天来修改</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">8</div>
          <div style="flex: 1">批量导出视频：不生成预览视频，混剪完成后自动导出视频，无需等待混剪完成</div>
        </div>
      </div>
      <div class="guide-dialog-body" v-else>
        <div class="guide-item">
          <div class="guide-index">1</div>
          <div style="flex: 1">上传爆款视频：可选择视频文件上传、也可通过抖音分享链接上传</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">2</div>
          <div style="flex: 1">选择爆款视频后点击一键复刻按钮</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">3</div>
          <div style="flex: 1">选择数字人形象，并设置声音、音乐和字幕样式</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">4</div>
          <div style="flex: 1">进入文案编辑页，可选择 AI 批量生成或手动添加文案</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">5</div>
          <div style="flex: 1">在文案列表中，可以修改或删除已生成的文案。</div>
        </div>
        <div class="guide-item">
          <div class="guide-index">6</div>
          <div style="flex: 1">点击生成按钮，后台将自动完成视频制作。</div>
        </div>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import {delAction, getAction, postAction} from "@/api/api";
import {marked} from "marked";
import {mapGetters} from "vuex";
import axios from "axios";

export default {
  data() {
    return {
      searchText: '',
      activeTag: '全部推荐',
      select_hots: {},
      uploadDialogVisible: false,
      uploadFile: null,
      use_link: false,
      hotFileList: [],
      dy_link: '',
      withAsr: true,
      uploadTag: '',
      classifies: [
        {name: '行业热点', color: '#f97316'},
        {name: '产品展示', color: '#3b82f6'},
        {name: '口播', color: '#22c55e'},
        {name: '企业故事', color: '#a855f7'},
        {name: '教程干货', color: '#f97316'},
        {name: '生活Vlog', color: '#22c55e'},
        {name: '搞笑段子', color: '#a855f7'},
        {name: '特效转场', color: '#f97316'},
        {name: 'AIGC', color: '#22c55e'},
        {name: '活动宣传', color: '#a855f7'},
      ],
      classify: '行业热点',
      loading: false,
      dotCount: 1,
      dotTimer: null,
      dot: '.',
      menuStyle: {
        position: 'fixed',
        top: '0',
        left: '0',
        border: '1px solid #eee',
        'border-radius': '6px',
        'background-color': '#fff',
        'z-index': 9999
      },
      rightMenuVisible: false,
      rightItem: {},
      previewDialogVisible: false,
      preview_src: '',
      isPlaying: false,
      renameDialogVisible: false,
      form: {
        original: '',
        name: ''
      },
      renameId: '',
      detailDialogVisible: false,
      segments: [],
      logInfo: {},
      activeCollapse: '',

      guideVisible: false,
      nextType: 'hot_montage',
      aspectRatio: 0,
    }
  },
  computed: {
    ...mapGetters("generate", ["figureTasks"]),
    processFile() {
      return this.figureTasks.filter((item) => item.status === 'pending' && item.video_type === 'hot_video');
    },
    hots() {
      let data = this.figureTasks.filter((item) => item.status === 'success' && item.video_type === 'hot_video');
      return data.map(item => ({...item, isHover: false}))
    },
    filter_hots() {
      let filteredItems = this.hots;

      if (this.searchText) {
        filteredItems = filteredItems.filter(item =>
            item.name.includes(this.searchText) ||
            item.tag.split(/[,，]/).includes(this.searchText)
        );
      }

      if (this.activeTag !== '全部推荐') {
        filteredItems = filteredItems.filter(item => item.category === this.activeTag);
      }

      return filteredItems
    }
  },
  mounted() {
    this.initData()
    this.startDotAnimation();
    this.$store.dispatch("generate/pollFigureTasks");
  },
  beforeDestroy() {
    clearInterval(this.dotTimer);
  },
  methods: {
    marked,
    startDotAnimation() {
      this.dotTimer = setInterval(() => {
        this.dotCount = this.dotCount % 3 + 1;
        this.dot = '.'.repeat(this.dotCount);
      }, 1000);
    },
    formattedDuration(duration) {
      const totalSeconds = parseInt(duration.toFixed(0));
      const minutes = Math.floor(totalSeconds / 60);
      const seconds = totalSeconds % 60;
      const formattedSeconds = seconds < 10 ? `0${seconds}` : seconds;
      return `${minutes}:${formattedSeconds}`;
    },
    tagFilter(name) {
      this.activeTag = name
    },
    selectVideo(item) {
      this.select_hots = item
      sessionStorage.setItem('select_hots', JSON.stringify(this.select_hots))
    },
    handleRightClick(item, event) {
      event.preventDefault();
      this.rightItem = item
      this.rightMenuVisible = true;
      this.menuStyle.left = Math.min(window.innerWidth - 173, event.clientX) + 'px'
      this.menuStyle.top = event.clientY + 'px'
      document.body.addEventListener("click", this.bodyClick);
    },
    bodyClick() {
      this.rightMenuVisible = false;
      this.rightItem = {}
      document.body.removeEventListener("click", this.bodyClick);
    },
    preview() {
      this.preview_src = this.rightItem.filepath
      this.aspectRatio = this.rightItem.height / this.rightItem.width;
      this.previewDialogVisible = true
    },
    beforePreviewClose() {
      this.isPlaying = false;
      if (this.$refs.video) {
        this.$refs.video.pause()
        this.preview_src = ''
      }
      this.previewDialogVisible = false;
    },
    rename() {
      this.form.original = this.rightItem.name
      this.form.name = ''
      this.renameId = this.rightItem.id
      this.renameDialogVisible = true
    },
    sureRename() {
      let params = {
        figure_id: this.renameId,
        name: this.form.name  ,
      };
      postAction("/figure/update_name", params).then((res) => {
        if (res.data.status === "success") {
          this.$message.success("重命名成功");
          this.$store.dispatch("generate/pollFigureTasks");
        } else {
          this.$alert(res.data.message,'重命名失败')
        }
        this.renameDialogVisible = false;
      }).catch((err) => {
        this.$alert(err,'重命名错误')
      });
    },
    removeHot() {
      this.deleteId = this.rightItem.id
      this.$confirm('此操作将删除该爆款视频, 是否继续?', '删除爆款视频', {
        type: 'warning'
      }).then(() => {
        delAction("/figure/delete", {ids: this.deleteId}).then((res) => {
          if (res.data.status === "success") {
            this.$message.success("删除成功");
            this.$store.dispatch("generate/pollFigureTasks");
          } else {
            this.$alert(res.data.message, "删除失败")
          }
        }).catch((err) => {
          this.$alert(err, "删除错误")
        });
      }).catch(() => {
        this.$message({type: 'info', message: '已取消删除'});
      });
    },
    showDetail() {
      this.logInfo = this.rightItem
      if (this.logInfo.asr_enabled) {
        this.logInfo.content = this.logInfo.segments.map(segment => segment.asr_text ? segment.asr_text : '').join('')
      }
      this.segments = this.rightItem.segments
      this.detailDialogVisible = true
    },
    initData() {
      this.select_hots = JSON.parse(sessionStorage.getItem('select_hots')) || {}
      this.nextType = sessionStorage.getItem('next_type') || 'hot_montage'
    },
    beforeUploadClose() {
      if (this.loading) {
        this.$alert('请等待上传完成后再关闭窗口','上传提示')
        return false;
      }
      this.uploadFile = null
      this.withAsr = true
      this.tag = ''
      this.uploadDialogVisible = false
    },
    handleUploadHot({ file }) {
      console.log(file)
    },
    handleHotChange(file, fileList) {
      this.hotFileList = fileList
    },
    handleHotRemove(file, fileList) {
      this.hotFileList = fileList
    },
    handleExceed(files, fileList) {
      this.$alert(`当前限制选择 6 个文件，本次选择了 ${files.length} 个文件，共选择了 ${files.length + fileList.length} 个文件`,'批量上传限制提醒');
    },
    handleSubmit() {
      if (!this.use_link) {
        if (this.hotFileList.length === 0) {
          this.$message.warning("请至少选择一个爆款视频文件上传！");
          return;
        }
        this.loading = true
        this.uploadByFile()
        return;
      }

      if (!this.dy_link) {
        this.$alert('请在输入框内粘贴抖音视频链接。','上传提示')
        return;
      }
      this.loading = true
      this.uploadByDyLink()
    },
    uploadByFile() {
      const formData = new FormData();
      this.hotFileList.forEach((file) => {
        formData.append("file", file.raw); // 将文件添加到 FormData 中
      });
      formData.append('withAsr', this.withAsr);
      formData.append('category', this.classify);
      formData.append('tag', this.uploadTag);
      formData.append('user_id', sessionStorage.getItem('token'));

      axios.post("http://127.0.0.1:6006/figure/add_hot_video", formData,{
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      }).then((res) => {
        if (res.data.status === "success") {
          this.loading = false
          this.$store.dispatch("generate/pollFigureTasks");
          this.$message.success("上传成功");
          this.beforeUploadClose();
        }else {
          this.loading = false
          this.$alert(res.data.message, "上传失败");
        }
      }).catch((err) => {
        this.loading = false
        this.$alert(err, "上传错误");
      })
    },
    uploadByDyLink() {
      let params = {
        url: this.dy_link,
        tag: this.uploadTag,
        withAsr: this.withAsr,
        category: this.classify,
      }
      postAction('/figure/add_hot_video_by_link', params, 600000).then(res => {
        if (res.data.status === 'success') {
          this.$notify({
            title: "上传提示",
            message: `已创建爆款视频上传任务`,
            duration: 5000,
            type: "success",
          });
        } else {
          this.$notify({
            title: "上传提示",
            message: `创建爆款视频上传任务失败，${res.data.message}`,
            duration: 0,
            type: "error",
          });
        }
        this.loading = false
        this.uploadDialogVisible = false
        this.$store.dispatch("generate/pollFigureTasks");
      })
    },

    duplicate() {
      if (!this.select_hots.id) {
        this.$alert('请先选择一个要复刻的爆款视频','提示')
      }
      sessionStorage.setItem('video_path', '/material')
      this.$router.push({path: '/material'})
    },
    back() {
      sessionStorage.setItem('video_path', '/video')
      this.$router.push({path: '/video'})
    }
  }
}
</script>

